"""Refresh the requested HTML acceptance report from retained test evidence."""
import html,json,pathlib,re,hashlib
root=pathlib.Path(__file__).resolve().parent/'evidence'
evidence=root/'exact-multisite-20261020'
read=lambda p:json.loads(p.read_text(encoding='utf-8'))
cohorts=[]
tap=(evidence/'linux-tests-m.log').read_text(encoding='utf-8')
assert re.search(r'# pass 441\b',tap) and re.search(r'# fail 0\b',tap)
cohorts.append(('Linux service regression',441,'linux-tests-m.log'))
for folder,title in [('goals-regression','Goal reviews and workflow context'),('workspace-regression','Workspace, history and connection recovery'),('peers-regression','Cross-tab SDK fill and Save'),('postfix-live-m','Real configured maker/checker: complete two-site goal')]:
    result=read(evidence/folder/'results.json')
    assert all(x['status']=='passed' for x in result['results'])
    cohorts.append((title,len(result['results']),folder+'/results.json'))
workflow=root/'immediate-phase-20261019/exact-multisite-workflow-m/results.json'
w=read(workflow);assert len(w['results'])==1 and w['results'][0]['status']=='passed'
cohorts.append(('WebSocket workflow: Customer, Note and Opportunity Save/readback (synthetic adapters)',1,'../immediate-phase-20261019/exact-multisite-workflow-m/results.json'))
total=sum(n for _,n,_ in cohorts);assert total==480
live=read(evidence/'postfix-live-m/results.json')
perf=read(evidence/'performance/results.json')['reports']
escaped=html.escape
rows=''.join(f'<tr><td>{escaped(title)}</td><td>{count}</td><td>0</td><td>0</td><td><a href="../exact-multisite-20261020/{path}">Evidence</a></td></tr>' for title,count,path in cohorts)
performance=''.join(f'<tr><td>{r["site"]}</td><td>{"SDK enabled" if r["sdkEnabled"] else "Host baseline"}</td><td>{r["rendererCpuPercent"]:.2f}%</td><td>{r["heapStartMiB"]:.2f} → {r["heapEndMiB"]:.2f} MiB</td><td>{r["network"]["idle"]["requests"]}</td><td>{r["network"]["idle"]["bytes"]:,} bytes</td></tr>' for r in perf)
images=[('local-separate-save-confirmation.png','Actual user Chrome: separate Save confirmation'),('company-only-private-handoff-review.png','Actual user Chrome: company-only instruction, no attached file or full-form sharing'),('recipient-search-field-review.png','Actual user Chrome: recipient search field review'),('postfix-live-m/completed-source.png','Fresh run: source goal completed, no clarification or recovery'),('postfix-live-m/completed-recipient.png','Fresh run: recipient actual result returned'),('postfix-live-m/public-host-result-controls.png','Fresh run: genosys search text and unchanged All transports; Search was not clicked')]
figures=''.join(f'<figure><a href="../exact-multisite-20261020/{path}"><img loading="lazy" src="../exact-multisite-20261020/{path}" alt="{escaped(caption)}"></a><figcaption>{escaped(caption)}</figcaption></figure>' for path,caption in images)
section=f'''<section class="card" id="exact-multisite-goal"><small>Latest scoped result · 20261020-review-gates-m</small><h1>Customer → paired MCP: complete goal verified</h1><p class="score">480/480 current checks passed · 100%</p><p>0 current failed · 0 current partial. These counts describe this release's regression and four live acceptance assertions; they are not a statistical model success rate, full Phase 1/2 certification or a sum of older report sections.</p>
<p><strong>Actual user Chrome:</strong> the exact requested Customer was saved once. Its original synthetic email still has exactly one record. The receiving MCP search text became <strong>genosys</strong> after review; <strong>All transports</strong> was preserved. No file was uploaded, no Search or provider was clicked, and no public submission occurred. That original run required a reconnect and recipient-role clarification, so its initial execution is recorded as <strong>recovered / partial</strong>, not a clean first-run pass.</p>
<p><strong>After generic fixes:</strong> a fresh isolated Chrome run repeated the same goal with unique email <code>{escaped(live['email'])}</code>. All five source steps and both recipient steps completed with zero clarifications and zero recorded interruptions. Independent readback found one new Customer and the original user's record still exactly once. Both peer sends shared no full-form values and no file; the company was included in the task instruction. The harness exercised every normal review as the delegated synthetic tester; no autonomous grant or policy bypass was used.</p>
<div class="scroll"><table><tr><th>Current cohort</th><th>Passed</th><th>Partial</th><th>Failed</th><th>Evidence</th></tr>{rows}</table></div>
<h2>Findings, fixes and recommendations</h2><div class="scroll"><table><tr><th>Observed finding</th><th>Fix / current result</th><th>Recommendation</th></tr>
<tr><td>Maker/checker confused a reviewed Save plan with automatic execution; fragmented remote work</td><td>Shared generic execution facts, constrained schema, bounded planning repairs and complete contiguous recipient assignments. Fresh real-model run passed.</td><td>Keep checker enabled and separate field review from Save confirmation. One successful run does not establish model reliability across all prompts.</td></tr>
<tr><td>Recipient interpreted forwarded “paired copilot” as its sender</td><td>Trusted sender/recipient role context; sender excluded from recipient execution targets, including replans. Other authorized third peers remain available.</td><td>Forward complete constraints. Wait for actual recipient result.</td></tr>
<tr><td>Background tab transport relied on browser timer scheduling</td><td>Authenticated protocol ping/pong replaces redundant application heartbeat; stale/revoked access still fails closed.</td><td>Pairing lifetime does not extend 15-minute idle authorization. Reconnect explicitly and resume unfinished work only.</td></tr>
<tr><td>Recovered run falsely summarized “no failures” and left stale current error</td><td>Retained bounded interruption history; recovered summaries use recorded facts and clarification counts. Successful goal recovery clears the current banner, not historical messages.</td><td>Inspect uncertain Save outcomes; never automatically repeat a Save.</td></tr>
<tr><td>Analytics allocated recurring timers before consent</td><td>Zero recurring analytics timers or click DOM traversal before opt-in; timers released on opt-out/destroy. Regression passed.</td><td>Keep analytics opt-in; monitor real devices and longer sessions.</td></tr>
<tr><td>First new harness setup selected a hidden control during initialization</td><td>Wait for enabled composer and visible Connections panel. Failed setup caused zero host effects and remains retained.</td><td>Separate harness readiness failures from product completion claims.</td></tr></table></div>
<h2>Measured idle overhead</h2><p>Fresh unpaired headless Chrome tabs, one approximately 60-second sample per variant, no model request/upload/analytics consent. CPU is summed renderer TaskDuration divided by elapsed time; heap is used JavaScript heap, not browser RSS. Host baseline substitutes only SDK mount.</p><div class="scroll"><table><tr><th>Website</th><th>Variant</th><th>Renderer CPU</th><th>JS heap start → end</th><th>Idle HTTP requests</th><th>Idle HTTP headers + bodies</th></tr>{performance}</table></div><p><a href="../exact-multisite-20261020/performance/results.json">Raw performance samples and limits</a>. No increasing retained-heap trend was observed in this short sample; this is not proof of long-session leak freedom, paired WebSocket wire cost, low-end-device performance, model response latency or 25-user backend capacity. Follow-up: longer paired soak and target-device measurements.</p>
<h2>Screenshots</h2><div class="grid">{figures}</div>
<h2>Audit and remaining scope</h2><ul><li><a href="../exact-multisite-20261020/prompt.txt">Exact requested prompt</a> · <a href="../exact-multisite-20261020/final-record-readback.json">Original record count: one</a> · <a href="../exact-multisite-20261020/postfix-live-m/saved-record-readback.json">Fresh run independent readback</a></li><li><a href="../exact-multisite-20261020/deployment-m.log">Deployment, health and unchanged checker settings</a> · <a href="../exact-multisite-20261020/docs-build.log">Documentation build</a></li><li>Maker/checker remains enabled, passive platform checker, 2,048-token cap. No global action policy, model selection, authorization expiry or parser-worker change.</li><li>Workflow regression used real SDK/server WebSocket delivery with isolated synthetic model/policy adapters. This release did not rerun the signed-in Flolah workflow engine with a fresh autonomous grant.</li><li>Native Safari/iOS, Android Chrome and full screen-reader testing remain user-deferred. Existing local/public registrations do not prove a fresh owner's real DNS/email onboarding.</li></ul><details><summary>Historical failures and recovered original run retained</summary><ul><li><a href="../exact-multisite-20261020/local-saved-and-peer-inspect-review.png">Original Save followed by offline peer stop</a></li><li><a href="../exact-multisite-20261020/recipient-role-failure-before-clarification.png">Original recipient role failure</a></li><li><a href="../exact-multisite-20261020/sender-final-summary.png">Original incorrect no-failures summary (fixed afterward)</a></li><li><a href="../exact-multisite-20261020/postfix-live/results.json">Harness initialization failure; zero Saves</a></li></ul></details></section>'''
p=root/'goal-plans-20261020/index.html';document=p.read_text(encoding='utf-8')
document=re.sub(r'<section class="card" id="exact-multisite-goal">.*?</section>','',document,flags=re.S)
document=document.replace('<main>','<main>'+section,1);p.write_text(document,encoding='utf-8')
manifest={str(p.relative_to(evidence)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(evidence.rglob('*')) if p.is_file() and p.name!='manifest.sha256.json'}
(evidence/'manifest.sha256.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
print(f'Updated requested report: {total} current checks, all passed; historical recovered original kept separate.')
